    public static class UgoFoscolo
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Federigo II aspirava a riunire l'Italia sotto un solo principe, una sola forma di governo e una sola lingua; e tramandarla a' suoi successori potentissima fra le monarchie d'Europa [...].", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "gli schiavi non sono, generalmente parlando, fatti dai tiranni, ma bensì gli schiavi fanno i tiranni.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il dolore in chi manca di pane è più rassegnato.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "il primo motore di tutte le azioni è la noia, la quale ci fa cercare occupazioni e desiderj nuovi, quando sono soddisfatti quelli che ci rodevano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La vendetta è una passione di natura ignea; se le darete luogo ed aria, si svapora e si spegne; se la comprimerete, andrà serpeggiando insidiosa e scoppierà col delitto e col tradimento.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Lo stile assoluto e sicuro del libro dei Delitti e delle Pene e l'elegante trattato del Galiani sulle Monete vivranno nobile ed eterno retaggio tra noi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Non son chi fui.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "O Italiani, io vi esorto alle storie.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Qui la povertà è vergogna che nessun merito lava.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Una parte degli uomini opera senza pensare, l'altra pensa senza operare.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A egregie cose il forte animo accendono | l'urne de' forti, o Pindemonte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A' generosi | giusta di gloria dispensiera è morte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Anche la Speme, | ultima Dea, fugge i sepolcri; e involve | tutte cose l'obblio nella sua notte", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Celeste è questa | corrispondenza di amorosi sensi, | celeste dote è negli umani", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sol chi non lascia eredità d'affetti | poca gioia ha dell'urna.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ahi! sugli estinti | non sorge fiore, ove non sia d'umane | lodi onorato e d'amoroso pianto", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Gli occhi dell'uom cercan morendo | il Sole: e tutti l'ultimo sospiro | mandano i petti alla fuggente luce", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Già il dotto e il ricco ed il patrizio vulgo, | decoro e mente al bello italo regno, | nelle adulate reggie ha sepoltura | già vivo, e i stemmi unica laude.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Quel grande | che temprando lo scettro a' regnatori | gli allòr ne sfronda, ed alle genti svela | di che lagrime grondi e di che sangue", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E tu onore di pianti, Ettore, avrai, | ove fia santo e lagrimato il sangue | per la patria versato, e finché il Sole | risplenderà su le sciagure umane.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A rifare l'Italia bisogna disfare le sètte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il tempo, che in sé è indefinibile, si misura soltanto dagli avvenimenti, e quello è maggiore corso di tempo che mena seco più numerosi, più forti e più memorabili eventi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E il biasimo dietro le spalle è pure la buona cosa! si può profittarne senza essere obbligati, e l'amor proprio non è ferito.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "chi preferisce l'onore alla vita è padrone di tutti coloro che vogliono avvilirlo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "questo so bene ch'io né per ripulse, né per favori, né per lodi né per biasimi mi rimoverò mai dal mio proponimento.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Si può bensì anche in mezzo alle ingiustizie sentirsi giusto, forte e libero; e la dignità dell'uomo si vendica più nel sopportare nobilmente, che nel lamentarsi e gridare invano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La noja proviene o da debolissima coscienza dell'esistenza nostra, per cui non ci sentiamo capaci di agire, o da coscienza eccessiva, per cui vediamo di non poter agire quanto vorremmo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Per me stimo il danaro da più di tutte quelle cose che il danaro può dare, e da meno delle cose che il danaro non può dare, e che pure sono ottime a questa misera vita degli uomini.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "le sciocche e laide abitudini sono le corruzioni della nostra natura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "una battaglia, per quanto sia prospera, dissangua anche il vincitore.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "le passioni passano, ma le sciagure restano perpetue nella nostra vita; e se non possiamo evitarle, non dobbiamo almeno esacerbarle co' nostri rimorsi, e renderle irremediabili.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "gli uomini sono pronti a ripigliarsi la stima che concedono, quando non la vedano alimentata da molte e perpetue prove di fatti.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "quando per giovar debolmente ad altri si corre rischio di nuocere gravemente a se stessi, l'intricarsene è pazzia da bastone", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sappi che la malignità, la cattiveria, e l'ignoranza sono bestie ferocissime perché sono codarde; e perché sono codarde s'avventano sopra il debole, e tremano dinanzi a chi si difende.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "l'umana prudenza prevede, ma non provvede.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la maggiore e più stolta incoerenza si è quella di voler fare a modo del mondo, temendo più le sue opinioni, che i giudizj della nostra propria coscienza.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Provvidenza non abbandona mai chi non abbandona se stesso.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "non v'è animale più invidioso del letterato", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "è meglio esser uomo senza danari, che l'aver danari senz'essere uomo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "in tutte le cose v'è il male e il bene; basta saperli distinguere: rassegnarsi al male, e giovarsi del bene.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "non può essere mai che l'uomo giusto e compassionevole sia davvero infelice, e in tutti i guai la sua propria coscienza gli serve di consolazione e di usbergo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "il disprezzare non è da tutti.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la troppa età è data dal cielo in pena del desiderio di troppo vivere.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sdegno il verso che suona e che non crea.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tre vaghissime donne a cui le trecce | infiora di felici itale rose | giovinezza, e per cui splende più bello | sul lor sembiante il giorno, all'ara vostra | sacerdotesse, o care Grazie, io guido.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ma se danza, | vedila! tutta l'armonia del suono scorre dal suo bel corpo, e dal sorriso | della sua bocca; e un moto, un atto, un vezzo | manda agli sguardi venustà improvvisa.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tornino i grandi | Occhi fatali al lor natio sorriso", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E in te beltà rivive, | l'aurea beltate ond'ebbero | ristoro unico a' mali | le nate a vaneggiar menti mortali.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Fiorir sul caro viso | veggo la rosa; tornano | i grandi occhi al sorriso | insidïando", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Itale genti, se Virtù suo scudo / su voi non stende, Libertà vi nuoce", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "a chi non ha patria non istà bene l'essere sacerdote, né padre.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Forse perché della fatal quïete | tu sei l'immago a me sì cara vieni | o Sera!", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E mentre io guardo la tua pace, dorme | quello spirto guerrier ch'entro mi rugge.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Amor fra l'ombre inferne | seguirammi immortale, onnipotente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Né più mai toccherò le sacre sponde | ove il mio corpo fanciulletto giacque, | Zacinto mia, che te specchi nell'onde | del greco mar da cui vergine nacque | Venere", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Colui che l'acque | cantò fatali", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "bello di fama e di sventura | baciò la sua petrosa Itaca Ulisse", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tu non altro che il canto avrai del figlio, | o materna mia terra, a noi prescrisse | il fato illacrimata sepoltura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Un dì, s'io non andrò sempre fuggendo | di gente in gente, me vedrai seduto | su la tua pietra, o fratel mio, gemendo | il fior de' tuoi gentili anni caduto.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Breve è la vita, e lunga è l'arte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Che è mai l'uomo? Il coraggio fu sempre dominatore dell'universo perché tutto è debolezza e paura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il coraggio non deve dare diritto per opprimere il debole.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Natura siede qui solitaria e minacciosa, e caccia da questo suo regno tutti i viventi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Noi chiamiamo pomposamente virtù tutte quelle azioni che giovano alla sicurezza di chi comanda e alla paura di chi serve.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sciagurati coloro che, per non essere scellerati, hanno bisogno della religione.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Se gli uomini si conducessero sempre al fianco la morte, non servirebbero sì vilmente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Ragione? – è come il vento; ammorza le faci, ed anima gl'incendj.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Io non odio persona al mondo, ma vi sono cert'uomini ch'io ho bisogno di vedere soltanto da lontano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Cos'è l'uomo se tu lo abbandoni alla sola ragione fredda, calcolatrice? scellerato, e scellerato bassamente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Facciamo tesoro di sentimenti cari e soavi i quali ci ridestino per tutti gli anni, che ancora forse tristi e perseguitati ci avanzano, la memoria che non siamo sempre vissuti nel dolore.", Author = "Ugo Foscolo" },
        };
    }
}